head.script:
scwin.__resizeEle = function() {
    WebSquare.wUnit.getJq("body").css("width", "450px");
    WebSquare.wUnit.getJq("#grd_internet").css("width", "450px");
}
scwin.fireOver = function(node) {
    if (document.createEventObject) {
        node.fireEvent('onmouseover');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('mouseover', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onmouseover == 'function') {
        node.onmouseover();
    }
}
scwin.checkSize = function() {
    if (WebSquare.wUnit.getObjById($p.id + 'grd_internet_tooltip').render.clientWidth === 246) {
        return true;
    }
    return false;
}
scwin.setVal = function() {
    scwin.fireOver(WebSquare.wUnit.getDomById('grd_internet_cell_1_2'));
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 2. 브라우저의 창을 임의로 줄인다.
    //2. Decrease the browser window randomly.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.__resizeEle()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. 요금제 두번째 컬럼을 마우스오버한다.
    //3. Mouse over the second column.
    WebSquare.wUnit.addCommand("set", "scwin.setVal()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. 툴팁이 사이즈에 맞게 생성된다. (기존에는 무조건 한줄로 나옴)
    //3. Tooltips are created to fit the size. (Previously unconditional one line)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grd_internet_tooltip').css('display')", "block");
    WebSquare.wUnit.addCommand("assert", "scwin.checkSize()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
